def _quarter_profit_risk(con, symbols, base):
    """Return latest quarterly net-profit YoY and pause flag, using PIT cumulative values."""
    if not symbols:
        return pd.DataFrame(columns=['latest_report_period', 'latest_np_yoy',
                                     'previous_np_yoy', 'risk_pause'])
    lst = ','.join("'" + str(s).replace("'", "''") + "'" for s in symbols)
    fin = con.execute(f"""
        select symbol, report_period, max(item_value) as cumulative_profit
        from src.financial_statement_items
        where symbol in ({lst}) and item_code='net_profit'
          and announce_date is not null and announce_date <= DATE '{base}'
          and regexp_matches(report_period, '^[0-9]{{4}}Q[1-4]$')
        group by symbol, report_period
    """).df()
    if fin.empty:
        return pd.DataFrame(columns=['latest_report_period', 'latest_np_yoy',
                                     'previous_np_yoy', 'risk_pause'])

    cumulative = fin.pivot_table(index='symbol', columns='report_period',
                                 values='cumulative_profit', aggfunc='max')

    def quarter_number(period):
        return int(period[:4]) * 4 + int(period[-1]) - 1

    def single_quarter(symbol, period):
        if symbol not in cumulative.index or period not in cumulative.columns:
            return np.nan
        value = cumulative.at[symbol, period]
        if pd.isna(value):
            return np.nan
        quarter = int(period[-1])
        if quarter == 1:
            return float(value)
        previous = f'{period[:4]}Q{quarter - 1}'
        if previous not in cumulative.columns:
            return np.nan
        previous_value = cumulative.at[symbol, previous]
        if pd.isna(previous_value):
            return np.nan
        return float(value - previous_value)

    results = []
    for symbol in cumulative.index:
        periods = sorted((p for p in cumulative.columns if str(p)[-2:] in
                          ('Q1', 'Q2', 'Q3', 'Q4') and not pd.isna(cumulative.at[symbol, p])),
                         key=quarter_number)
        yoy_by_period = {}
        for period in periods:
            year = int(period[:4])
            prior_period = f'{year - 1}{period[4:]}'
            current_single = single_quarter(symbol, period)
            prior_single = single_quarter(symbol, prior_period)
            if (pd.isna(current_single) or pd.isna(prior_single) or prior_single <= 0):
                continue
            yoy_by_period[period] = (current_single / prior_single - 1) * 100

        if not yoy_by_period:
            continue
        latest = max(yoy_by_period, key=quarter_number)
        prior = f'{latest[:4]}Q{int(latest[-1]) - 1}' if latest[-1] != '1' \
            else f'{int(latest[:4]) - 1}Q4'
        latest_yoy = yoy_by_period[latest]
        prior_yoy = yoy_by_period.get(prior, np.nan)
        pause = latest_yoy < -30 or (not pd.isna(prior_yoy) and prior_yoy < -30)
        results.append(dict(symbol=symbol, latest_report_period=latest,
                            latest_np_yoy=latest_yoy, previous_np_yoy=prior_yoy,
                            risk_pause=pause))
    if not results:
        return pd.DataFrame(columns=['latest_report_period', 'latest_np_yoy',
                                     'previous_np_yoy', 'risk_pause'])
    return pd.DataFrame(results).set_index('symbol')


def _atomic_csv(frame, path):
    directory = os.path.dirname(os.path.abspath(path))
    fd, temporary = tempfile.mkstemp(prefix='.' + os.path.basename(path) + '.',
                                     suffix='.tmp', dir=directory)
    os.close(fd)
    try:
        frame.to_csv(temporary, index=False, encoding='utf-8-sig')
        os.replace(temporary, path)
    except Exception:
        try:
            os.remove(temporary)
        except FileNotFoundError:
            pass
        raise


